fn lane(y: i32, h: i32, win: i32, me: i32) {
    let r: i32 = host::http::ready(h);
    if r == 1 {
        host::display::fill_rect(40, y, 12, 12, 0x22bb44);
        host::display::draw_string(64, y + 2, "READY", 0x22bb44, 1);
        host::display::draw_number(130, y, host::http::status(h), 0x66ddff, 2);
    } else if r < 0 {
        host::display::fill_rect(40, y, 12, 12, 0xbb2222);
        host::display::draw_string(64, y + 2, "ERROR", 0xbb2222, 1);
    } else {
        host::display::fill_rect(40, y, 12, 12, 0xaa7700);
        host::display::draw_string(64, y + 2, "PENDING", 0xaa7700, 1);
    }
    if win == me {
        host::display::draw_string(300, y + 2, "WINNER", 0xffffff, 2);
    }
}

fn frame(t: i32) {
    host::display::clear(0x0b0d11);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::http::get("https://example.com/", 20));
        host::display::state_set(2, host::http::get("https://www.rust-lang.org/", 26));
        host::display::state_set(0, 1);
    }
    let ha: i32 = host::display::state_get(1);
    let hb: i32 = host::display::state_get(2);
    if host::display::state_get(3) == 0 {
        if host::http::ready(ha) == 1 {
            host::display::state_set(3, 1);
        } else if host::http::ready(hb) == 1 {
            host::display::state_set(3, 2);
        }
    }
    let win: i32 = host::display::state_get(3);
    host::display::draw_string(140, 60, "FETCH RACE", 0xffffff, 2);
    host::display::draw_string(40, 140, "LANE A", 0x888888, 1);
    lane(170, ha, win, 1);
    host::display::draw_string(40, 260, "LANE B", 0x888888, 1);
    lane(290, hb, win, 2);
    if win == 0 {
        host::display::draw_string(40, 400, "RACING...", 0xaa7700, 2);
    }
    host::display::present();
}
